from typing import List

class Solution:
    def majorityElement(self, nums: List[int]) -> List[int]:
        counter = {}
        for num in nums:
            if num not in counter:
                counter[num] = 0
            counter[num] += 1
        return [num for num in counter if counter[num] > len(nums)/3]

# Input: [1,1,1,3,3,2,2,2]
